steps.script:
var orphans = []
for sid in StratagemManager.stratagems:
	if StratagemManager.is_faction_stratagem(str(sid)) and StratagemManager.get_stratagem_owner(str(sid)) == 0:
		orphans.append(sid)
return orphans

var rows = []
for c in tree.root.get_node("Main/StratagemPanel/Scroll/List").get_children():
	if str(c.name).begins_with("Strat_"):
		rows.append(str(c.name))
var kos = rows.filter(func(r): return r.contains("kult_of_speed"))
var wh = rows.filter(func(r): return r.contains("war_horde"))
return "kult_of_speed=%d war_horde=%d" % [kos.size(), wh.size()]
